"""Hand-authored small planes, chips and grain finishing at native resolution."""
from PIL import ImageDraw
from draw_proofs import c
from finish_c5 import remap

# Per-look coordinate lists, not generated or randomized texture.
# Each row is y:x,length pairs. Short native runs connect to existing planes.
def runs(im,rows,ink):
 d=ImageDraw.Draw(im)
 for row in rows.split(';'):
  if not row.strip():continue
  y,spans=row.split(':');y=int(y)
  for span in spans.split():
   x,length=map(int,span.split(','));d.rectangle((x,y,x+length-1,y+1),fill=c(*ink))

